function podiumLabels(score: number[]): string[] {
  const medals = ["Gold", "Silver", "Bronze"];
  return score.map(s => {
    let better = 0;
    for (const t of score) if (t > s) better++;
    return better < 3 ? medals[better] : String(better + 1);
  });
}

