class Solution:
    def podiumLabels(self, score: List[int]) -> List[str]:
        medals = ["Gold", "Silver", "Bronze"]
        out = []
        for s in score:
            better = sum(1 for t in score if t > s)
            out.append(medals[better] if better < 3 else str(better + 1))
        return out

