class MaxHeap {
  private a: [number, number][] = [];
  get size() { return this.a.length; }
  push(x: [number, number]) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] >= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): [number, number] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] > a[m][0]) m = l;
        if (r < a.length && a[r][0] > a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function podiumLabels(score: number[]): string[] {
  const medals = ["Gold", "Silver", "Bronze"];
  const heap = new MaxHeap();
  score.forEach((s, i) => heap.push([s, i]));
  const answer: string[] = new Array(score.length);
  for (let k = 0; heap.size > 0; k++) {
    const [, i] = heap.pop();
    answer[i] = k < 3 ? medals[k] : String(k + 1);
  }
  return answer;
}

